{
  "presses": ["L-ring-home", "L-pinky-bottom", "L-middle-bottom", "R-pinky-top"],
  "note": "T3 omit L-pinky-top. Expect returned letters = {3 of G,N,T,Y}+E(R-pinky-top). Missing from {G,N,T,Y} ⇒ letter on L-pinky-top. Use rotation notice to track E next."
}

{
  "presses": ["L-ring-home", "L-pinky-bottom", "L-middle-bottom", "R-pinky-top"],
  "note": "S4{Lrh,Lpb,Lmb,Lrb}={G,L,N,T}; Rot={Lih,Lih-in,Lpt}. Next press {Lrh,Lpb,Lmb,Rpt}; use Rpt∈{G,N,T}⇒L on one of first3."
}

{
  "presses": ["L-ring-home", "L-pinky-bottom", "R-pinky-top", "R-middle-home"],
  "note": "t6: L-ring-bottom=L; R-pinky-top=D (pre-rot); {L-ring-home,L-pinky-bottom,L-middle-bottom}={G,N,T}. t7 press Lrh,Lpb,Rpt,Rmh to resolve Lrh/Lpb."
}

{
  "presses": ["L-pinky-bottom", "L-ring-bottom", "L-index-top", "L-index-home"],
  "note": "T19 chord Lpb+Lrb+Lit+Lih. If no rotation: letters include F on Lpb and L on Lrb; remaining two map Lit/Lih; R-middle-top=the leftover from {J,X,Y}."
}
